const fs=require("fs"),p=require("path").posix,cp=require("child_process");
const R="src/ServerScriptService";
const rd=(f)=>{try{return JSON.parse(fs.readFileSync(f,"utf8").replace(/^\uFEFF/,""))}catch(e){return null}};
const attrs=(f)=>((rd(f)||{}).attributes)||{};
const isInit=(f)=>/^init\.luau$/.test(p.basename(f));
const metaOf=(f)=>isInit(f)?p.join(p.dirname(f),"init.meta.json"):f.replace(/\.luau$/,".meta.json");
const isModuleDir=(d)=>fs.existsSync(p.join(d,"init.luau"));
const parentDir=(f)=>isInit(f)?p.dirname(p.dirname(f)):p.dirname(f);
const owner=(f)=>{let o=f;let d=parentDir(f);while(d.startsWith(R+"/")){if(isModuleDir(d))o=p.join(d,"init.luau");d=p.dirname(d)}return o};
const cascade=(f,name)=>{let d=parentDir(f);while(d.startsWith(R)){if(!isModuleDir(d)){const v=attrs(p.join(d,"init.meta.json"))[name];if(v!==undefined)return v}if(d===R)break;d=p.dirname(d)}return undefined};
const relocates=(f0)=>{const f=owner(f0);const a=attrs(metaOf(f));if(a.RelocateToServerScriptService===true)return false;if(a.RelocateToReplicatedStorage!==undefined)return a.RelocateToReplicatedStorage===true;return cascade(f,"RelocateToReplicatedStorage")===true};
const clientOnly=(f0)=>{const f=owner(f0);const a=attrs(metaOf(f));if(a.ClientOnly!==undefined)return a.ClientOnly===true;return cascade(f,"ClientOnly")===true};
const changed=()=>cp.execFileSync("git",["status","--porcelain","--untracked-files=all"],{encoding:"utf8"}).split(/\r?\n/).filter(Boolean).map((l)=>l.slice(3).replace(/^"|"$/g,"")).filter((f)=>fs.existsSync(f));
const walk=(d,acc=[])=>{if(!fs.existsSync(d))return acc;for(const e of fs.readdirSync(d,{withFileTypes:true})){const f=p.join(d,e.name);if(e.isDirectory())walk(f,acc);else acc.push(f)}return acc};
const src=(f)=>fs.readFileSync(f,"utf8");
const fail=(m)=>{console.log(m);process.exit(1)};
const f="src/ServerScriptService/Modules/Systems/Gameplay/RoundSystem/SystemPackage/RoundServerService.luau";
if(!fs.existsSync(f))fail("RoundServerService.luau is missing");
const s=src(f);
for(const name of ["Init","Start"]){
const m=new RegExp("function RoundServerService[:.]"+name+"\\([^)]*\\)([\\s\\S]*?)\\nend").exec(s);
if(!m)continue;
const body=m[1];
const y=body.search(/task\.wait\(|:Wait\(|\bwait\(|\bwhile\s|\brepeat\s|IsServerLoaded/);
const sp=body.search(/task\.(spawn|defer)\(|coroutine\.(wrap|resume)\(/);
if(y!==-1&&(sp===-1||sp>y))fail("RoundServerService:"+name+" still waits or loops before handing off to a new thread");
}
console.log("RoundServerService's Init and Start hand any waiting or looping to a new thread");
